  ('114d617c-1e8e-478d-bd14-eca555f2a30a', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Brand Strategy, Purpose, and Positioning', 'This opening topic frames identity design as strategic communication, not surface styling. Students learn to connect visual decisions to purpose, audience, differentiation, and organizational behavior.', 0),
  ('617093e8-8e55-4421-9162-f184aa0d8342', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '114d617c-1e8e-478d-bd14-eca555f2a30a', 'subtopic'::public.curated_course_node_type, 'Purpose and promise', 'Students clarify what the brand exists to do and what expectation it creates for people.', 0),
