  ('4f3da21c-57bb-4a13-be45-11a07a8df107', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'fd4ffc54-406d-4d32-b4b8-6b142c0af2ea', 'concept'::public.curated_course_node_type, 'Research-backed creative brief', null, 2),
