  ('2dfde21f-4d26-4e38-a202-3dc7457ccfe7', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '9b9bf243-366b-4cec-9e47-578ef9502a31', 'subtopic'::public.curated_course_node_type, 'Brand equity', 'Students learn how recognition, associations, trust, and experience create value over time.', 0),
  ('460bed79-0432-4b4c-a6e5-741046855afa', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '2dfde21f-4d26-4e38-a202-3dc7457ccfe7', 'concept'::public.curated_course_node_type, 'Awareness and associations', null, 0),
