  ('70ed3745-f3ad-41ae-80be-92343912760a', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '9b9bf243-366b-4cec-9e47-578ef9502a31', 'subtopic'::public.curated_course_node_type, 'Portfolio decisions', 'Students consider when to extend, consolidate, rename, or separate identities.', 2),
