  ('97c6db9a-36d0-43c3-9aee-a569f035c16f', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '70ed3745-f3ad-41ae-80be-92343912760a', 'concept'::public.curated_course_node_type, 'Sub-brand roles', null, 1),
  ('c1be5b9a-c678-4a94-9bfe-433b863b61f3', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '70ed3745-f3ad-41ae-80be-92343912760a', 'concept'::public.curated_course_node_type, 'Migration and governance', null, 2),
  ('1a370895-75c9-4f45-9fcf-67ee604c18e0', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Naming, Verbal Identity, Voice, and Tone', 'Brand identity is both visual and verbal. Students learn to shape names, taglines, message hierarchy, and tone so language and design feel like one system.', 3);
