  ('00bc6dc8-149e-426a-9da1-cb5b48dfe0da', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Typography for Identity Systems', 'Typography carries personality, hierarchy, and usability. This topic teaches students to choose and use type as a strategic brand voice across print and digital contexts.', 5),
  ('b00fcc47-2e64-48ae-95e6-9c6265ec433b', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '00bc6dc8-149e-426a-9da1-cb5b48dfe0da', 'subtopic'::public.curated_course_node_type, 'Typeface selection', 'Students learn to match type choices to strategy, audience, and implementation reality.', 0),
  ('dd4038a1-2d8e-43de-9bfa-4dee2376ebf4', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'b00fcc47-2e64-48ae-95e6-9c6265ec433b', 'concept'::public.curated_course_node_type, 'Classification and personality', null, 0),
  ('157bc803-2087-4fcf-89b3-01c616977ffb', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'b00fcc47-2e64-48ae-95e6-9c6265ec433b', 'concept'::public.curated_course_node_type, 'Licensing and availability', null, 1),
  ('e5529add-0b96-4d45-bfe9-e25bc65e05d8', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'b00fcc47-2e64-48ae-95e6-9c6265ec433b', 'concept'::public.curated_course_node_type, 'Variable fonts and digital use', null, 2),
  ('522e7d4b-c9dd-4dea-abca-70bf689416ed', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '00bc6dc8-149e-426a-9da1-cb5b48dfe0da', 'subtopic'::public.curated_course_node_type, 'Typographic system', 'The point is to create hierarchy and rhythm that can scale across many assets.', 1),
  ('c0577c32-7edf-414f-81f9-3382ef775ed0', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '522e7d4b-c9dd-4dea-abca-70bf689416ed', 'concept'::public.curated_course_node_type, 'Display, text, and UI roles', null, 0),
  ('f32760d1-13a8-4755-8824-827d512752a3', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '522e7d4b-c9dd-4dea-abca-70bf689416ed', 'concept'::public.curated_course_node_type, 'Scale, spacing, and grids', null, 1),
  ('64893252-ae01-4952-b3fe-879734e1006b', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '522e7d4b-c9dd-4dea-abca-70bf689416ed', 'concept'::public.curated_course_node_type, 'Language support and accessibility', null, 2),
  ('9bd9f9d3-bce8-4fee-bfa7-228c8f745832', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '00bc6dc8-149e-426a-9da1-cb5b48dfe0da', 'subtopic'::public.curated_course_node_type, 'Custom type and lettering', 'Students explore when a custom wordmark or type modification is worth the effort.', 2),
  ('9a31de74-931d-44ca-b0fa-a3ddf5bf60ee', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '9bd9f9d3-bce8-4fee-bfa7-228c8f745832', 'concept'::public.curated_course_node_type, 'Letterform refinement', null, 0),
  ('8d9cb9c4-4cef-4b6c-950f-79ee65445301', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '9bd9f9d3-bce8-4fee-bfa7-228c8f745832', 'concept'::public.curated_course_node_type, 'Optical balance', null, 1),
  ('a2ffb352-4d7f-4997-8d5e-c7f2c7ff1160', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '9bd9f9d3-bce8-4fee-bfa7-228c8f745832', 'concept'::public.curated_course_node_type, 'Consistency with the broader system', null, 2),
  ('872eb134-a700-47b7-9763-7697e26e9e03', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Color, Form, Image, and Graphic Language', 'A brand becomes recognizable through repeated visual behavior. Students build palettes, forms, imagery, icons, patterns, and compositional rules that support a coherent identity.', 6),
  ('6b9c67bb-59ea-4e6a-aa7f-3b261f54d7dd', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '872eb134-a700-47b7-9763-7697e26e9e03', 'subtopic'::public.curated_course_node_type, 'Color systems', 'Students learn to make palettes that are expressive, accessible, and reproducible.', 0);
