values
  ('e882f3b1-e1ee-4292-887e-b91537037901', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '6b9c67bb-59ea-4e6a-aa7f-3b261f54d7dd', 'concept'::public.curated_course_node_type, 'Primary and secondary palettes', null, 0),
