  ('a6f004d6-17cf-4f34-8564-6e5824ab9432', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '6b9c67bb-59ea-4e6a-aa7f-3b261f54d7dd', 'concept'::public.curated_course_node_type, 'Contrast and color roles', null, 2),
  ('79244f38-7573-40f7-a5f4-3935de47364d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '872eb134-a700-47b7-9763-7697e26e9e03', 'subtopic'::public.curated_course_node_type, 'Graphic elements', 'The point is to create useful design ingredients beyond the logo.', 1),
  ('7893b07a-0e61-4a1a-a35a-eacec872b3cb', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '79244f38-7573-40f7-a5f4-3935de47364d', 'concept'::public.curated_course_node_type, 'Patterns and shapes', null, 0),
  ('f75c7dcf-6f11-41ab-9b2d-5bb4e3486a33', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '79244f38-7573-40f7-a5f4-3935de47364d', 'concept'::public.curated_course_node_type, 'Icon and illustration styles', null, 1),
  ('37d3c170-de81-4037-88cf-1637c375fa12', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '79244f38-7573-40f7-a5f4-3935de47364d', 'concept'::public.curated_course_node_type, 'Photography and art direction', null, 2),
  ('43ad39e2-fa87-45ae-902b-21e50dbc6ff2', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '872eb134-a700-47b7-9763-7697e26e9e03', 'subtopic'::public.curated_course_node_type, 'Visual consistency', 'Students learn how repetition and variation create a living system.', 2),
  ('260b789c-1461-4671-895b-68b6dfc9a02d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '43ad39e2-fa87-45ae-902b-21e50dbc6ff2', 'concept'::public.curated_course_node_type, 'Motifs and signature moves', null, 0),
  ('ef498e18-41fc-4860-90a9-f22ab2d7a412', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '43ad39e2-fa87-45ae-902b-21e50dbc6ff2', 'concept'::public.curated_course_node_type, 'Rules for variation', null, 1),
  ('1ce80ca3-fca5-42ac-aff7-a1d4da20e5a1', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '43ad39e2-fa87-45ae-902b-21e50dbc6ff2', 'concept'::public.curated_course_node_type, 'Avoiding sameness and clutter', null, 2),
  ('9a8f8697-c7d5-459e-9a96-5161277d89ee', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Identity Systems, Grid Logic, and Design Principles', 'This topic shifts students from individual deliverables to systems thinking. A strong identity creates rules that other designers can use without weakening the brand.', 7),
  ('d4f352db-d1d2-4a01-b7bc-153f0d54cc74', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '9a8f8697-c7d5-459e-9a96-5161277d89ee', 'subtopic'::public.curated_course_node_type, 'System principles', 'Students identify the few rules that make the identity recognizable.', 0),
  ('95de0735-1d0d-4086-8ef8-11ace8e25349', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd4f352db-d1d2-4a01-b7bc-153f0d54cc74', 'concept'::public.curated_course_node_type, 'Core design principles', null, 0),
  ('6088aaf6-e852-4138-a134-7b7a2997502a', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd4f352db-d1d2-4a01-b7bc-153f0d54cc74', 'concept'::public.curated_course_node_type, 'Flexible versus fixed elements', null, 1),
  ('ad721b06-8fe8-4bb8-bde1-eba9ceb39fc2', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd4f352db-d1d2-4a01-b7bc-153f0d54cc74', 'concept'::public.curated_course_node_type, 'System boundaries', null, 2),
  ('6241c5da-c9ff-4317-be2d-6e5667ab6eba', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '9a8f8697-c7d5-459e-9a96-5161277d89ee', 'subtopic'::public.curated_course_node_type, 'Layout and grid logic', 'The gist is to make applications feel related even across different formats.', 1),
  ('dfd75409-3311-4d45-baf1-b4db97b71571', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '6241c5da-c9ff-4317-be2d-6e5667ab6eba', 'concept'::public.curated_course_node_type, 'Grid structures', null, 0),
  ('60d64b77-3d84-47e1-8f4c-2b05bba369f3', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '6241c5da-c9ff-4317-be2d-6e5667ab6eba', 'concept'::public.curated_course_node_type, 'Spacing and proportion', null, 1),
  ('1e4c162a-49b5-4fc3-8205-eae157ac0929', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '6241c5da-c9ff-4317-be2d-6e5667ab6eba', 'concept'::public.curated_course_node_type, 'Modular layouts', null, 2),
  ('925681d6-0736-4be9-a83b-a69cb1d9347d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '9a8f8697-c7d5-459e-9a96-5161277d89ee', 'subtopic'::public.curated_course_node_type, 'Scalability', 'Students learn to design for both small assets and complex campaigns.', 2),
  ('3311689a-fd1b-4aaa-a750-d30eaa0eba47', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '925681d6-0736-4be9-a83b-a69cb1d9347d', 'concept'::public.curated_course_node_type, 'Asset families', null, 0),
  ('fe257c50-24f5-4871-b6fe-a06768e11246', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '925681d6-0736-4be9-a83b-a69cb1d9347d', 'concept'::public.curated_course_node_type, 'Templates and variants', null, 1),
  ('824172d9-7142-44a3-97e1-febc77684670', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '925681d6-0736-4be9-a83b-a69cb1d9347d', 'concept'::public.curated_course_node_type, 'Growth without fragmentation', null, 2),
  ('fdb7a787-78ee-4529-8f69-d725102fb469', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Brand Applications Across Touchpoints', 'Identity design becomes real through use. Students apply the system across varied touchpoints and learn to adjust while preserving recognizability.', 8),
  ('d856abcc-c877-49c9-9623-5ff984c0908d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'fdb7a787-78ee-4529-8f69-d725102fb469', 'subtopic'::public.curated_course_node_type, 'Print and packaging', 'Students practice translating identity into tangible, production-aware formats.', 0),
  ('d24226b6-2833-4c64-82a0-4ed2c4049453', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd856abcc-c877-49c9-9623-5ff984c0908d', 'concept'::public.curated_course_node_type, 'Stationery and collateral', null, 0),
  ('57421bfa-beb8-471f-bd72-7e8de394a893', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd856abcc-c877-49c9-9623-5ff984c0908d', 'concept'::public.curated_course_node_type, 'Packaging hierarchy', null, 1),
  ('cebbdf86-9233-48ce-af60-b24144d2953d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd856abcc-c877-49c9-9623-5ff984c0908d', 'concept'::public.curated_course_node_type, 'Materials, finishes, and print constraints', null, 2),
  ('3f191904-3b14-445f-8436-5ff49042ecb2', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'fdb7a787-78ee-4529-8f69-d725102fb469', 'subtopic'::public.curated_course_node_type, 'Digital and social', 'The point is to create brand behavior for fast-moving, screen-based contexts.', 1),
  ('80cd95f7-05d7-42f2-a7d5-08a6087bec9d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '3f191904-3b14-445f-8436-5ff49042ecb2', 'concept'::public.curated_course_node_type, 'Social templates', null, 0),
  ('fe48757e-7a16-4857-8536-a9bab7e9dc07', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '3f191904-3b14-445f-8436-5ff49042ecb2', 'concept'::public.curated_course_node_type, 'Web and mobile assets', null, 1),
  ('2be07a82-4ffe-4ae6-81bb-20885a71f235', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '3f191904-3b14-445f-8436-5ff49042ecb2', 'concept'::public.curated_course_node_type, 'Thumbnails, avatars, and responsive marks', null, 2),
  ('0416aeac-9c44-44f8-8334-700ff029901d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'fdb7a787-78ee-4529-8f69-d725102fb469', 'subtopic'::public.curated_course_node_type, 'Spatial and experiential', 'Students consider how identity functions in environments and public interactions.', 2),
  ('43cc0e25-0a10-4bfe-963e-2e131d080803', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '0416aeac-9c44-44f8-8334-700ff029901d', 'concept'::public.curated_course_node_type, 'Signage and wayfinding', null, 0),
  ('42b996f7-116e-45a9-896f-6faa7d02e7b3', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '0416aeac-9c44-44f8-8334-700ff029901d', 'concept'::public.curated_course_node_type, 'Events and retail', null, 1),
  ('0d5a439f-98e8-4e3c-965c-d770e7d358ea', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '0416aeac-9c44-44f8-8334-700ff029901d', 'concept'::public.curated_course_node_type, 'Environmental graphics', null, 2),
  ('ba2dd522-f3f3-43f8-a298-60c0a2e234b3', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Digital Brand Systems, UI Components, and Accessibility', 'Modern identities must work inside interfaces and design systems. Students learn how brand choices become tokens, components, states, and accessible experiences.', 9),
  ('706c5358-1fae-4980-a5bf-84e8da32d9a6', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'ba2dd522-f3f3-43f8-a298-60c0a2e234b3', 'subtopic'::public.curated_course_node_type, 'Design tokens', 'Students translate brand choices into maintainable digital variables.', 0),
  ('a7127c51-7ce8-42e8-94f3-23ef20ceae0e', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '706c5358-1fae-4980-a5bf-84e8da32d9a6', 'concept'::public.curated_course_node_type, 'Color tokens', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('6ad56203-5591-4c4d-ae4c-01c783703b20', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '706c5358-1fae-4980-a5bf-84e8da32d9a6', 'concept'::public.curated_course_node_type, 'Typography tokens', null, 1),
  ('c10ec19b-194f-495c-b8db-b674fd3c01f4', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '706c5358-1fae-4980-a5bf-84e8da32d9a6', 'concept'::public.curated_course_node_type, 'Spacing, radius, and elevation rules', null, 2),
  ('adb8dffc-6a13-4687-8a81-bdb93cba1501', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'ba2dd522-f3f3-43f8-a298-60c0a2e234b3', 'subtopic'::public.curated_course_node_type, 'UI components', 'The point is to preserve brand expression while supporting usability.', 1),
  ('37544481-c2c8-4822-ad23-4086cacf7ca5', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'adb8dffc-6a13-4687-8a81-bdb93cba1501', 'concept'::public.curated_course_node_type, 'Buttons, forms, cards, and navigation', null, 0),
