  ('820243a3-1730-4cd8-825e-842d0fbcd92b', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'adb8dffc-6a13-4687-8a81-bdb93cba1501', 'concept'::public.curated_course_node_type, 'Component documentation', null, 2),
  ('e5aeadba-d525-4089-991c-09e75604f3be', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'ba2dd522-f3f3-43f8-a298-60c0a2e234b3', 'subtopic'::public.curated_course_node_type, 'Accessibility', 'Students learn that brand consistency cannot override legibility, contrast, or inclusive use.', 2),
  ('faea7fb3-fe7f-4d73-b263-9275c42c8f80', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'e5aeadba-d525-4089-991c-09e75604f3be', 'concept'::public.curated_course_node_type, 'Contrast and color blindness', null, 0),
  ('a9786468-f263-428b-8437-5581b196aea5', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'e5aeadba-d525-4089-991c-09e75604f3be', 'concept'::public.curated_course_node_type, 'Readable type and motion sensitivity', null, 1),
  ('893f066c-a9f1-4391-92aa-e8d5f427fa38', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'e5aeadba-d525-4089-991c-09e75604f3be', 'concept'::public.curated_course_node_type, 'Alt text and semantic handoff', null, 2),
  ('6a563e2c-046b-4940-8267-0371dea6c5ab', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Motion, Sound, and Experiential Brand Behavior', 'Identity increasingly lives in time. This topic introduces motion, interaction, and sensory behavior as part of the brand system.', 10),
  ('739e7946-1940-4375-adfc-e0ed309e0000', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '6a563e2c-046b-4940-8267-0371dea6c5ab', 'subtopic'::public.curated_course_node_type, 'Motion principles', 'Students define how a brand moves so animation supports identity rather than decoration.', 0),
  ('2f28d55b-c9ef-4291-9379-f1717d7ae4cb', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '739e7946-1940-4375-adfc-e0ed309e0000', 'concept'::public.curated_course_node_type, 'Timing and easing', null, 0),
