  ('4635d434-415e-4db9-9ca5-181828c5647c', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '6a563e2c-046b-4940-8267-0371dea6c5ab', 'subtopic'::public.curated_course_node_type, 'Interactive behavior', 'The gist is to make brand expression responsive to user action.', 1),
  ('974b8395-463d-4723-82d5-245d3cf3599f', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '4635d434-415e-4db9-9ca5-181828c5647c', 'concept'::public.curated_course_node_type, 'Hover, tap, loading, and feedback states', null, 0),
  ('b336d449-7ee6-4f38-b6f7-2c93361d1c3b', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '4635d434-415e-4db9-9ca5-181828c5647c', 'concept'::public.curated_course_node_type, 'Microinteractions', null, 1),
  ('af875f28-9905-45b0-b986-b241722973df', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '4635d434-415e-4db9-9ca5-181828c5647c', 'concept'::public.curated_course_node_type, 'Error and success moments', null, 2),
  ('fbaae073-8b29-4121-80a4-8ad2bcf0968d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '6a563e2c-046b-4940-8267-0371dea6c5ab', 'subtopic'::public.curated_course_node_type, 'Sensory extensions', 'Students consider sound, haptics, and experience design where appropriate.', 2),
  ('c232d113-f96a-4ded-acbb-da6d0e61d10d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'fbaae073-8b29-4121-80a4-8ad2bcf0968d', 'concept'::public.curated_course_node_type, 'Sonic logos and cues', null, 0),
  ('8b845924-2f0d-4255-9db8-10d4c9c72869', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'fbaae073-8b29-4121-80a4-8ad2bcf0968d', 'concept'::public.curated_course_node_type, 'Event experience', null, 1),
  ('28bcf86d-1b67-4693-b746-fb2bf55c3c39', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'fbaae073-8b29-4121-80a4-8ad2bcf0968d', 'concept'::public.curated_course_node_type, 'Multisensory consistency', null, 2),
  ('d136ea02-b4ea-475f-9259-ba27a43061b1', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Brand Guidelines, Asset Libraries, and Governance', 'Guidelines turn design into implementation. Students learn to document rules, rationale, files, and examples so a brand can be used by many people without falling apart.', 11),
  ('68ae7928-aea6-4188-9538-fe49fa5f2f93', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd136ea02-b4ea-475f-9259-ba27a43061b1', 'subtopic'::public.curated_course_node_type, 'Guideline structure', 'Students learn what a useful brand guide must explain.', 0),
  ('e0dbfc83-914a-4790-a7b2-b1c4b98c3f5a', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '68ae7928-aea6-4188-9538-fe49fa5f2f93', 'concept'::public.curated_course_node_type, 'Logo rules', null, 0),
  ('9cd3c432-4a98-43af-b69f-7b708a8955fd', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '68ae7928-aea6-4188-9538-fe49fa5f2f93', 'concept'::public.curated_course_node_type, 'Color, type, image, and layout standards', null, 1),
  ('fb9d9a54-2ddf-40e6-bbec-ea00182c1cbb', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '68ae7928-aea6-4188-9538-fe49fa5f2f93', 'concept'::public.curated_course_node_type, 'Voice, examples, and rationale', null, 2),
  ('be3fbc0d-1a96-4b92-a5e5-de22f0dcb1be', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd136ea02-b4ea-475f-9259-ba27a43061b1', 'subtopic'::public.curated_course_node_type, 'Asset management', 'The point is to package files so teams can actually use them correctly.', 1),
  ('700e79e0-a02f-462c-8f37-4b9b8236cd6d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'be3fbc0d-1a96-4b92-a5e5-de22f0dcb1be', 'concept'::public.curated_course_node_type, 'File formats and naming', null, 0),
  ('ba1e0bc3-8aa2-4798-a6e6-7557dda2de83', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'be3fbc0d-1a96-4b92-a5e5-de22f0dcb1be', 'concept'::public.curated_course_node_type, 'Templates and libraries', null, 1),
  ('de03e424-1657-451c-a63c-f2abdcedc952', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'be3fbc0d-1a96-4b92-a5e5-de22f0dcb1be', 'concept'::public.curated_course_node_type, 'Version control', null, 2),
  ('bb5eb2ba-9ef3-42a6-bb80-2d472297a5ae', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd136ea02-b4ea-475f-9259-ba27a43061b1', 'subtopic'::public.curated_course_node_type, 'Governance', 'Students consider how brands are maintained after launch.', 2),
  ('4a1cc187-5351-4a4c-91f3-823979c3595a', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'bb5eb2ba-9ef3-42a6-bb80-2d472297a5ae', 'concept'::public.curated_course_node_type, 'Approval workflows', null, 0),
  ('bad6063f-981d-4104-97f1-5ae0703a597a', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'bb5eb2ba-9ef3-42a6-bb80-2d472297a5ae', 'concept'::public.curated_course_node_type, 'Use cases and exceptions', null, 1),
  ('d6ea9161-c9be-4736-b6a9-5f280802c264', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'bb5eb2ba-9ef3-42a6-bb80-2d472297a5ae', 'concept'::public.curated_course_node_type, 'Training and stewardship', null, 2),
  ('bdd2a980-ecfa-4d64-aac0-8f7b7b1b0fd4', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Rebranding, Refreshes, and Identity Migration', 'Rebranding is not a blank slate. Students learn to preserve useful equity, diagnose real problems, and manage change across audiences and touchpoints.', 12),
  ('67cb9ff3-eea7-4b24-ac3f-765b5b8897c6', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'bdd2a980-ecfa-4d64-aac0-8f7b7b1b0fd4', 'subtopic'::public.curated_course_node_type, 'Brand audit', 'Students evaluate what should be kept, repaired, retired, or amplified.', 0),
  ('be0c7acc-46ae-4f6d-b02a-493d2a506071', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '67cb9ff3-eea7-4b24-ac3f-765b5b8897c6', 'concept'::public.curated_course_node_type, 'Equity inventory', null, 0),
  ('ee9b2c59-02aa-477e-ba1a-d3e2e1403983', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '67cb9ff3-eea7-4b24-ac3f-765b5b8897c6', 'concept'::public.curated_course_node_type, 'Stakeholder interviews', null, 1);
