values
  ('91e89594-b0a9-4a67-8d4f-fdeb8cde217e', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '67cb9ff3-eea7-4b24-ac3f-765b5b8897c6', 'concept'::public.curated_course_node_type, 'Touchpoint and consistency audit', null, 2),
  ('96286f26-8a87-4c4e-a35b-b3a195c68444', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'bdd2a980-ecfa-4d64-aac0-8f7b7b1b0fd4', 'subtopic'::public.curated_course_node_type, 'Redesign strategy', 'The gist is to decide the degree of change before changing the visuals.', 1),
  ('fe0c1adc-57a9-43b4-afa6-b4ab768257fa', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '96286f26-8a87-4c4e-a35b-b3a195c68444', 'concept'::public.curated_course_node_type, 'Refresh versus rebrand', null, 0),
  ('c8012d39-0426-4c65-b170-93dfeda7a2a1', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '96286f26-8a87-4c4e-a35b-b3a195c68444', 'concept'::public.curated_course_node_type, 'Migration risk', null, 1),
  ('5187a235-a128-4c40-9bee-33a15e69473f', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '96286f26-8a87-4c4e-a35b-b3a195c68444', 'concept'::public.curated_course_node_type, 'Launch narrative', null, 2),
  ('d386d1b2-eddd-49c6-80de-159474fe97d8', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'bdd2a980-ecfa-4d64-aac0-8f7b7b1b0fd4', 'subtopic'::public.curated_course_node_type, 'Implementation planning', 'Students learn how a redesign rolls out in the real world.', 2),
  ('fe3d2a43-2d65-4b54-8dc1-c932b8e6b91f', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd386d1b2-eddd-49c6-80de-159474fe97d8', 'concept'::public.curated_course_node_type, 'Phased rollout', null, 0),
  ('976353ba-bf1b-498e-b8fd-469f6871c2a0', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd386d1b2-eddd-49c6-80de-159474fe97d8', 'concept'::public.curated_course_node_type, 'Old-to-new asset mapping', null, 1),
  ('c9a8e61b-7f2b-4dcd-96ae-1494c8fbcf51', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'd386d1b2-eddd-49c6-80de-159474fe97d8', 'concept'::public.curated_course_node_type, 'Internal adoption and training', null, 2),
  ('fded4907-249c-4a99-b179-6dd19ecbec7a', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Global, Local, Inclusive, and Ethical Branding', 'This topic asks students to design with cultural intelligence and responsibility. Identity work can include, exclude, inspire, confuse, stereotype, or repair trust.', 13),
  ('4dc933a5-d76e-4a55-a431-59a613b9e527', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'fded4907-249c-4a99-b179-6dd19ecbec7a', 'subtopic'::public.curated_course_node_type, 'Cultural meaning', 'Students learn to research symbols, colors, language, and imagery across contexts.', 0),
  ('3927abbb-9f5a-4e20-8340-d14097af91b1', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '4dc933a5-d76e-4a55-a431-59a613b9e527', 'concept'::public.curated_course_node_type, 'Localization and translation', null, 0),
  ('5b6d2934-863d-4bc6-8be7-bd2797f57920', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '4dc933a5-d76e-4a55-a431-59a613b9e527', 'concept'::public.curated_course_node_type, 'Cultural codes and taboos', null, 1),
  ('b3fa1ed7-e920-4827-aaa6-86634d834ee0', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '4dc933a5-d76e-4a55-a431-59a613b9e527', 'concept'::public.curated_course_node_type, 'Avoiding appropriation and stereotypes', null, 2),
  ('12a6b64e-8f73-4118-9398-3cb2cffa212d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'fded4907-249c-4a99-b179-6dd19ecbec7a', 'subtopic'::public.curated_course_node_type, 'Inclusive identity', 'The point is to consider who is represented, who can use the system, and who may be harmed.', 1),
  ('8ac9b265-4425-44b0-9e04-d55420ca27b1', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '12a6b64e-8f73-4118-9398-3cb2cffa212d', 'concept'::public.curated_course_node_type, 'Representation and imagery', null, 0),
  ('a42c6bfe-a814-4e33-8759-95ea04ad4765', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '12a6b64e-8f73-4118-9398-3cb2cffa212d', 'concept'::public.curated_course_node_type, 'Accessibility as identity quality', null, 1),
  ('9463d3d1-58ce-405e-8b73-727b68ea1896', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '12a6b64e-8f73-4118-9398-3cb2cffa212d', 'concept'::public.curated_course_node_type, 'Inclusive naming and language', null, 2),
  ('43bfb301-ed42-405e-90a2-e1904eb4ff32', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'fded4907-249c-4a99-b179-6dd19ecbec7a', 'subtopic'::public.curated_course_node_type, 'Ethical practice', 'Students connect design choices to social, environmental, and reputational consequences.', 2),
  ('e8010bef-abaa-4568-9b87-6b7a294384ab', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '43bfb301-ed42-405e-90a2-e1904eb4ff32', 'concept'::public.curated_course_node_type, 'Greenwashing and authenticity', null, 0),
  ('bffd38fc-a717-458f-ae17-233cfd31f4fc', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '43bfb301-ed42-405e-90a2-e1904eb4ff32', 'concept'::public.curated_course_node_type, 'Dark patterns and manipulation', null, 1),
  ('e13b7d28-3300-4ec6-816d-6448dfcfebc4', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '43bfb301-ed42-405e-90a2-e1904eb4ff32', 'concept'::public.curated_course_node_type, 'Transparency and accountability', null, 2),
  ('7046f2b4-1555-444f-bcb6-8de247c86645', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Brand Measurement, Testing, and Critique', 'Identity systems should be judged by more than taste. Students learn to evaluate recognition, clarity, usability, distinctiveness, fit, and audience response.', 14),
  ('de03487c-0170-4f79-a617-66ad9d6f64fc', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '7046f2b4-1555-444f-bcb6-8de247c86645', 'subtopic'::public.curated_course_node_type, 'Qualitative testing', 'Students use critique and user feedback to identify strengths and problems.', 0),
  ('50e7370d-0dda-4178-a5ef-c6d79c2baedc', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'de03487c-0170-4f79-a617-66ad9d6f64fc', 'concept'::public.curated_course_node_type, 'Perception interviews', null, 0),
  ('cfea8f3e-9c4b-4205-b46e-a707001b8497', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'de03487c-0170-4f79-a617-66ad9d6f64fc', 'concept'::public.curated_course_node_type, 'Preference versus fit', null, 1),
  ('65822adc-d14c-4ae3-ba57-7d5c901f50fb', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'de03487c-0170-4f79-a617-66ad9d6f64fc', 'concept'::public.curated_course_node_type, 'Critique protocols', null, 2),
  ('cbc68ef3-6fdf-4f69-b50c-b30ab77ccb66', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '7046f2b4-1555-444f-bcb6-8de247c86645', 'subtopic'::public.curated_course_node_type, 'Quantitative indicators', 'The gist is to understand brand metrics without reducing design to numbers alone.', 1),
  ('65f581e2-a76f-48fa-b280-9172adc466bb', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'cbc68ef3-6fdf-4f69-b50c-b30ab77ccb66', 'concept'::public.curated_course_node_type, 'Recognition and recall', null, 0),
  ('735ae25f-052e-4a5d-bf1b-05f9a651d15c', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'cbc68ef3-6fdf-4f69-b50c-b30ab77ccb66', 'concept'::public.curated_course_node_type, 'Distinctiveness and association', null, 1),
  ('acd51e71-c2f9-4fd1-949e-3557a9ea88b0', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'cbc68ef3-6fdf-4f69-b50c-b30ab77ccb66', 'concept'::public.curated_course_node_type, 'Brand equity and tracking', null, 2),
  ('28aaa020-2f21-4623-adb8-5f74bee4506d', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '7046f2b4-1555-444f-bcb6-8de247c86645', 'subtopic'::public.curated_course_node_type, 'Design critique', 'Students learn to defend work with evidence and revise without losing the idea.', 2),
  ('21d1e0d9-c0ff-4d80-a571-50ed8863b790', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '28aaa020-2f21-4623-adb8-5f74bee4506d', 'concept'::public.curated_course_node_type, 'Strategic rationale', null, 0),
  ('263bea3c-a5de-4b6b-92e1-2fce5e327021', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '28aaa020-2f21-4623-adb8-5f74bee4506d', 'concept'::public.curated_course_node_type, 'Craft standards', null, 1),
  ('683e3ca5-eac1-4c4e-95e8-990c4bc3af07', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', '28aaa020-2f21-4623-adb8-5f74bee4506d', 'concept'::public.curated_course_node_type, 'Iteration logs', null, 2),
  ('c5220390-3dd9-4300-85a2-1f7a2ffc9bfa', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', null, 'topic'::public.curated_course_node_type, 'Case Studies from Leading Studios and Institutions', 'Case studies train taste and judgment. Students study professional identity systems to understand how strategy, craft, implementation, and public reception interact.', 15),
  ('9e7bcde1-ed90-4a1d-aaf9-fae72cd121f8', 'c5d6e7f8-9a0b-4c73-8e23-3f4a5b6c7d03', 'c5220390-3dd9-4300-85a2-1f7a2ffc9bfa', 'subtopic'::public.curated_course_node_type, 'Historical cases', 'Students learn from durable identity systems and the conditions that made them last.', 0),
